const config = Object.values(this.ENTITY_CONFIG).find(c => c.apiEntity === entityName);
const isCompanyBound = config ? config.isCompanyBound : false;
const currentCompanyId = this.globalSelectedCompany?.companyId || null;

// 3. Generate Cache Key
// If it's company-bound, the cache key MUST include the company ID.
// e.g. "pay_schedules" becomes "pay_schedules_55"
let cacheKey = key;
if (isCompanyBound) {
    if (!currentCompanyId) {
        console.warn(`Cannot load ${entityName}: No Company ID selected.`);
        return Promise.resolve({});
    }
    cacheKey = `${key}_${currentCompanyId}`;
}

if (this._cache[cacheKey]) {
    return this._cache[cacheKey];
}

const fields = this.helpers._getFieldsToSelect(entityName);
const uniqueFields = [...new Set(fields)];

const queryParts = [`select=${uniqueFields.join(",")}`];

if (isCompanyBound && currentCompanyId) {
    queryParts.push(`CompanyId=${currentCompanyId}`);
}

const query = queryParts.join("&");

this._cache[cacheKey] = this.payrollApiService.get({
    entity: entityName,
    page: 1,
    limit: 1000,
    query,
    customEntityKey
}).then(res => {
    const list = res.entities || res || [];

    return list.reduce((acc, item) => {
        acc[item.Id] = item;
        return acc;
    }, {});
}).catch(err => {
    console.error(`Failed to load ${entityName}`, err);
    this._cache[cacheKey] = null;
    throw err;
});

return this._cache[cacheKey];

