const map = await this._ensureStaticList(key, entityType, customEntityKey);
const items = Object.values(map);

// Build the base options array
const options = items.map(item => ({
    label: item[labelField], // Will be undefined for workers initially
    value: item.Id,
    ...item
}));

// Hydrate Worker Names
if (entityType === 'worker') {
    const workerIds = options.map(opt => opt.value);

    // Leverage the existing batch resolver to get the users linked to these workers
    const users = await this.resolvers.batch.resolveUsersByWorkerId(workerIds);

    options.forEach((opt, index) => {
        const user = users[index];
        // Format the full name, fallback to "Worker [ID]" if orphaned
        const fullName = user ? `${user.FirstName || ''} ${user.LastName || ''}`.trim() : `Worker ${opt.value}`;

        opt.label = fullName;
        opt.Name = fullName; // Populate the Name field just in case future forms expect it
    });
}

// 3. Return alphabetically sorted options for better UI experience
return options.sort((a, b) => (a.label || '').localeCompare(b.label || ''));

const defaultFields = ["Id"];
const configEntry = Object.values(this.ENTITY_CONFIG).find(
    c => c.apiEntity === apiEntityName
);

if (configEntry && configEntry.selectFields) {
    return defaultFields.concat(configEntry.selectFields);
}

return defaultFields.concat(["Name"]);

