}

const currentCompanyId = this.globalSelectedCompany?.companyId;
if (!currentCompanyId) {
    console.warn(`Cannot resolve ${entity}: No Company ID selected.`);
    return Promise.resolve([]);
}

// 1. Generate Field and Company-Scoped Cache Key (e.g. user_by_WorkerId_55 vs user_by_Id_55)
const cacheKey = `${entity}_by_${idField}_${currentCompanyId}`;
if (!this._cache[cacheKey]) this._cache[cacheKey] = {};
const companyCache = this._cache[cacheKey];

const uniqueIds = [...new Set(idArr.filter(id => id !== null && id !== undefined))];
const missingIds = uniqueIds.filter(id => !companyCache[id]);

// 2. Batch Fetch with Chunking & Scoping
if (missingIds.length > 0) {
    const CHUNK_SIZE = 50;
    const chunks = [];

    for (let i = 0; i < missingIds.length; i += CHUNK_SIZE) {
        chunks.push(missingIds.slice(i, i + CHUNK_SIZE));
    }

    const fetchPromises = chunks.map(chunk => {
        const query = `${idField}_in=${chunk.join(',')}&CompanyId=${currentCompanyId}`;
        return this.payrollApiService.get({
            entity: entity,
            limit: chunk.length,
            query: query
        }).then(res => res.entities || (Array.isArray(res) ? res : []));
    });

    const batchFetchPromise = Promise.all(fetchPromises)
        .then(results => results.flat())
        .catch(err => {
            console.warn(`Batch resolve ${entity} failed`, err);
            missingIds.forEach(id => delete companyCache[id]);
            return [];
        });

    missingIds.forEach(id => {
        companyCache[id] = batchFetchPromise.then(list => {
            return list.find(item => String(item[idField]) === String(id)) || null;
        });
    });
}

// 3. Return Order-Preserved Promises
const promiseList = idArr.map(id => {
    if (!id) return Promise.resolve(null);
    return companyCache[id] || Promise.resolve(null);
});

return Promise.all(promiseList);

