if (!this._cache.users) this._cache.users = {};

// Filter out nulls/undefined and deduplicate
const uniqueIds = [...new Set(idArr.filter(id => id !== null && id !== undefined))];

// 2. Identify Missing IDs
const missingIds = uniqueIds.filter(id => !this._cache.users[id]);

// 3. Batch Fetch Missing Items
if (missingIds.length > 0) {
    const query = `Id_in=${missingIds.join(',')}`;

    // Create ONE shared promise for the network request
    const batchFetchPromise = this.payrollApiService.get({
        entity: 'user', // Hits the collection endpoint (e.g. /api/user?Id_in=...)
        query: query
    }).then(res => {
        // Handle various backend response shapes ({ entities: [...] } vs [...])
        const users = res.entities || (Array.isArray(res) ? res : []);
        return users;
    }).catch(err => {
        console.warn("Batch resolveUsers failed", err);
        // Invalidate the failed IDs so they can be retried later
        missingIds.forEach(id => delete this._cache.users[id]);
        return [];
    });

    // 4. Update Cache (The "Split" Strategy)
    // Map the SINGLE batch promise to specific promises for each ID.
    missingIds.forEach(id => {
        this._cache.users[id] = batchFetchPromise.then(allUsers => {
            // Find this specific user in the batch results
            // Using loose equality (==) handles string/number mismatches (e.g. "5" vs 5)
            const match = allUsers.find(u => u.Id == id);
            return match || null;
        });
    });
}

// 5. Return Results in Order
// Map the original input array to the cached promises
const promiseList = idArr.map(id => {
    if (!id) return Promise.resolve(null);
    return this._cache.users[id] || Promise.resolve(null);
});

return Promise.all(promiseList);

if (!workerIdArr || !Array.isArray(workerIdArr) || workerIdArr.length === 0) {
    return Promise.resolve([]);
}

