if (!this._cache.usersByWorkerId) this._cache.usersByWorkerId = {};

const uniqueIds = [...new Set(workerIdArr.filter(id => id !== null && id !== undefined))];

// 2. Identify Missing Worker IDs
const missingIds = uniqueIds.filter(id => !this._cache.usersByWorkerId[id]);

// 3. Batch Fetch with Chunking and Explicit Limits
if (missingIds.length > 0) {
    const CHUNK_SIZE = 50; // Safe threshold for URL length limits
    const chunks = [];

    // Split missingIds into bite-sized arrays
    for (let i = 0; i < missingIds.length; i += CHUNK_SIZE) {
        chunks.push(missingIds.slice(i, i + CHUNK_SIZE));
    }

    // Map chunks to parallel API request promises
    const fetchPromises = chunks.map(chunk => {
        const query = `WorkerId_in=${chunk.join(',')}`;
        // Explicitly pass limit matching the chunk size to bypass the default 25 limit
        return this.payrollApiService.get({
            entity: 'user',
            limit: chunk.length,
            query: query
        }).then(res => {
            return res.entities || (Array.isArray(res) ? res : []);
        });
    });

    // Combine all chunk requests into a single master resolution promise
    const batchFetchPromise = Promise.all(fetchPromises)
        .then(results => {
            // Flatten the array of arrays into a single array of user objects
            return results.flat();
        })
        .catch(err => {
            console.warn("Batch resolveUsersByWorkerId failed", err);
            // Evict from cache on failure so a retry can occur later
            missingIds.forEach(id => delete this._cache.usersByWorkerId[id]);
            return [];
        });

    // 4. Update Cache
    missingIds.forEach(wId => {
        this._cache.usersByWorkerId[wId] = batchFetchPromise.then(allUsers => {
            return allUsers.find(u => String(u.WorkerId) === String(wId)) || null;
        });
    });
}

// 5. Return Results
const promiseList = workerIdArr.map(wId => {
    if (!wId) return Promise.resolve(null);
    return this._cache.usersByWorkerId[wId] || Promise.resolve(null);
});

return Promise.all(promiseList);

