if (!entity) return null;

const hydrated = { ...entity };
const tasks = [];

Object.keys(hydrated).forEach(key => {
    if (key.endsWith("Id") && key.length > 2) {

        const entityType = key.slice(0, -2);
        const id = hydrated[key];

        if (entityType.includes("CalculationMethod") && id != null) {
            // Hardcode resolution to avoid backend calls
            if (id == 1) hydrated[entityType] = "FLAT";
            else if (id == 2) hydrated[entityType] = "PERCENT";
            else hydrated[entityType] = id; // Fallback

            return;
        }

        // --- Skip WorkerId in the standard loop ---
        if (entityType === "Worker") {
            return; // Handled below in special logic
        }

        // --- Standard Resolution ---
        const config = this.ENTITY_CONFIG[entityType];

        if (config && id != null) {
            const promise = this.resolvers.resolveEntity(entityType, id)
                .then(item => {
                    hydrated[entityType] = item ? item[config.label] : id;
                });
            tasks.push(promise);
        }
    }
});

// Handle Users (Special Logic for CreatedBy/UpdatedBy)
['CreatedBy', 'UpdatedBy'].forEach(key => {
    const userId = hydrated[key];
    if (userId != null) {
        tasks.push(
            this.resolvers.resolveUser(userId).then(user => {
                hydrated[key] = user ? `${user.FirstName || ''} ${user.LastName || ''}`.trim() : userId;
            })
        );
    }
});

// Handle Worker Name Hydration (Special Logic for WorkerId)
// A Worker's name comes from the User table, so we use the batch resolver
if (hydrated.WorkerId != null) {
    tasks.push(
        this.resolvers.batch.resolveUsersByWorkerId([hydrated.WorkerId]).then(users => {
            const user = users[0]; // The batch resolver returns an array matching the input order
            hydrated.Worker = user ? `${user.FirstName || ''} ${user.LastName || ''}`.trim() : hydrated.WorkerId;
        })
    );
}

await Promise.all(tasks);
return hydrated;

if (key) {
    this._cache[key] = null;
} else {
    Object.keys(this._cache).forEach(k => this._cache[k] = null);
}
